-- The two checklists published on 2026-11-15: When the News Is Too Much
-- (News) and Splitting the Housework Fairly (Chores).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-15`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-the-news-is-too-much', 'When the News Is Too Much', 'For when the news has taken over your attention and your mood. It fixes two times a day to look, turns the notifications off, swaps the feed for two sources, puts one thing you can actually do in front of you, and stops an hour before bed.', 'News', '["Pick two times a day to look and stick to them — the rest of the day does not need updating.", "Read it rather than watch it — text lets you stop, and video keeps deciding for you.", "Turn off notifications from news apps entirely — you do not need interrupting by the world.", "Choose two sources and leave the feed alone — a feed is built to keep you there, not to inform you.", "Do one thing that is actually in your reach — donate, write, show up, or help one person.", "Stop reading an hour before bed — the night is not when anything gets solved.", "Notice when you are refreshing rather than reading — refreshing is anxiety, not information.", "Talk to one person about it out loud — carrying it silently makes it feel bigger than it is.", "Let yourself be uninformed for a day — the world does not require your constant attention."]'::jsonb, 'as needed', array['Anxiety', 'Boundaries', 'Stress']::text[], 1, '2026-11-15T16:00:00+00:00'::timestamptz),
  ('splitting-the-housework-fairly', 'Splitting the Housework Fairly', 'For a household where the work is not landing evenly. It gets every task written down including the invisible ones, hands over ownership rather than help, trades by dread as much as minutes, and sets the standard out loud once.', 'Chores', '["Write down every task, including the invisible ones — remembering is work and belongs on the list.", "Pick who owns a task rather than who helps with it — owning means noticing it, not being asked.", "Stop asking to be asked — a job you have to request is still your job.", "Trade by how much you hate it, not by minutes — fairness is about dread as much as time.", "Set the standard out loud once — half of these arguments are two definitions of clean.", "Let them do it their way once it is theirs — redoing it silently is how ownership dies.", "Put the weekly reset in the calendar — a named hour beats waiting for somebody to crack.", "Review the split every few months — jobs and babies and seasons change what is fair.", "Pay for one thing if you can afford to — an hour of help is cheaper than the resentment."]'::jsonb, 'weekly', array['Relationships', 'Communication', 'Boundaries']::text[], 1, '2026-11-15T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
